import { type ConfigPlugin, withAppBuildGradle } from 'expo/config-plugins';

// The android folder is generated by `expo prebuild` and not kept in git, so the release
// signing setup is added here each time it is generated. Expo's template signs release
// builds with the shared debug key, which anyone can download.
//
// The key's location and passwords are Gradle properties: from ~/.gradle/gradle.properties
// on your PC, or from ORG_GRADLE_PROJECT_<name> environment variables in CI.
const RELEASE_SIGNING_CONFIG = `        release {
            def storeFilePath = project.findProperty('AUDIOSTASH_STORE_FILE')
            if (storeFilePath) {
                storeFile file(storeFilePath)
                storePassword project.findProperty('AUDIOSTASH_STORE_PASSWORD')
                keyAlias project.findProperty('AUDIOSTASH_KEY_ALIAS')
                keyPassword project.findProperty('AUDIOSTASH_KEY_PASSWORD')
            } else {
                // Fail release builds without the key. Otherwise Gradle quietly makes an APK
                // signed with nothing or the wrong key, which will not install over the app.
                project.gradle.taskGraph.whenReady { graph ->
                    if (graph.allTasks.any { it.name.contains('Release') }) {
                        throw new GradleException('AUDIOSTASH_STORE_FILE is not set. Release builds need the AudioStash key: see docs/deploy.md, "Build the app on your PC".')
                    }
                }
            }
        }
`;

const SIGNING_CONFIGS = /(\n {4}signingConfigs \{\n)/;
// The release build type, up to the signingConfig line in it. Its comments hold no braces.
const RELEASE_USES_DEBUG_KEY = /(\n {8}release \{[^}]*?signingConfig )signingConfigs\.debug/;

export function addReleaseSigning(buildGradle: string): string {
  if (buildGradle.includes('AUDIOSTASH_STORE_FILE')) return buildGradle;
  if (!SIGNING_CONFIGS.test(buildGradle) || !RELEASE_USES_DEBUG_KEY.test(buildGradle)) {
    throw new Error(
      'release-signing: android/app/build.gradle no longer has the expected layout. Update plugins/release-signing.ts for the new Expo template.',
    );
  }
  return buildGradle.replace(RELEASE_USES_DEBUG_KEY, '$1signingConfigs.release').replace(SIGNING_CONFIGS, `$1${RELEASE_SIGNING_CONFIG}`);
}

export const withReleaseSigning: ConfigPlugin = (config) =>
  withAppBuildGradle(config, (gradleConfig) => {
    gradleConfig.modResults.contents = addReleaseSigning(gradleConfig.modResults.contents);
    return gradleConfig;
  });
